# 贪吃蛇:用广度优先搜索走向最近的果子,走不到就找一个空格子。
from collections import deque
import npe

DIRS = [(0, -1), (1, 0), (0, 1), (-1, 0)]  # 上 右 下 左


def think(obs):
    w, h = obs["width"], obs["height"]
    blocked = {tuple(c) for s in obs["snakes"] if s["alive"] for c in s["body"]}
    food = {tuple(f) for f in obs["food"]}
    head = tuple(obs["snakes"][obs["me"]]["body"][0])
    queue = deque([(head, None)])
    seen = {head}
    fallback = None
    while queue:
        (x, y), first = queue.popleft()
        if (x, y) in food and first is not None:
            return {"dir": first}
        for d, (dx, dy) in enumerate(DIRS):
            c = (x + dx, y + dy)
            if c in seen or c in blocked or not (0 <= c[0] < w and 0 <= c[1] < h):
                continue
            seen.add(c)
            step = d if first is None else first
            if fallback is None:
                fallback = step
            queue.append((c, step))
    return {"dir": fallback if fallback is not None else 0}


npe.run(think)

// 贪吃蛇:避开障碍,靠近最近的果子。
import java.util.*;

public class Careful {
    static final int[] DX = {0, 1, 0, -1}, DY = {-1, 0, 1, 0};

    public static void main(String[] args) {
        Npe.run(obs -> {
            int w = obs.getInt("width"), h = obs.getInt("height"), me = obs.getInt("me");
            boolean[][] wall = new boolean[h][w];
            Npe.Json snakes = obs.get("snakes");
            for (int i = 0; i < snakes.size(); i++)
                for (int[] c : snakes.get(i).getGrid("body")) wall[c[1]][c[0]] = true;
            int[] head = snakes.get(me).getGrid("body")[0];
            int[][] food = obs.getGrid("food");
            int best = Integer.MIN_VALUE, dir = 0;
            for (int d = 0; d < 4; d++) {
                int x = head[0] + DX[d], y = head[1] + DY[d];
                if (x < 0 || y < 0 || x >= w || y >= h || wall[y][x]) continue;
                int near = 999;
                for (int[] f : food) near = Math.min(near, Math.abs(f[0] - x) + Math.abs(f[1] - y));
                int exits = 0;
                for (int k = 0; k < 4; k++) {
                    int a = x + DX[k], b = y + DY[k];
                    if (a >= 0 && b >= 0 && a < w && b < h && !wall[b][a]) exits++;
                }
                int score = exits * 6 - near;
                if (score > best) { best = score; dir = d; }
            }
            return Npe.action("dir", dir);
        });
    }
}

// 贪吃蛇:用洪水填充保证有路可走,再靠近果子。
#include "snake.h"
#include <algorithm>
#include <vector>

static const int DX[4] = {0, 1, 0, -1}, DY[4] = {-1, 0, 1, 0};

int think(const State *s) {
    std::vector<std::vector<int>> wall(s->height, std::vector<int>(s->width));
    for (int i = 0; i < s->snake_count; i++)
        if (s->snakes[i].alive)
            for (int k = 0; k < s->snakes[i].length; k++) wall[s->snakes[i].body[k].y][s->snakes[i].body[k].x] = 1;
    auto free_cell = [&](const std::vector<std::vector<int>> &g, int x, int y) {
        return x >= 0 && y >= 0 && x < s->width && y < s->height && !g[y][x];
    };
    const Snake &me = s->snakes[s->me];
    int best = -1000000, dir = UP;
    for (int d = 0; d < 4; d++) {
        int x = me.body[0].x + DX[d], y = me.body[0].y + DY[d];
        if (!free_cell(wall, x, y)) continue;
        auto g = wall;
        std::vector<Point> stack{{x, y}};
        g[y][x] = 1;
        int area = 0;
        while (!stack.empty()) {
            Point p = stack.back();
            stack.pop_back();
            area++;
            for (int k = 0; k < 4; k++)
                if (free_cell(g, p.x + DX[k], p.y + DY[k])) {
                    g[p.y + DY[k]][p.x + DX[k]] = 1;
                    stack.push_back({p.x + DX[k], p.y + DY[k]});
                }
        }
        int near = 999;
        for (int i = 0; i < s->food_count; i++) near = std::min(near, abs(s->food[i].x - x) + abs(s->food[i].y - y));
        int score = std::min(area, me.length * 3) * 20 - near;
        if (score > best) { best = score; dir = d; }
    }
    return dir;
}

/* 贪吃蛇:不撞墙不撞蛇,尽量靠近最近的果子。 */
#include "snake.h"

static const int DX[4] = {0, 1, 0, -1}, DY[4] = {-1, 0, 1, 0};

static int blocked(const State *s, int x, int y) {
    if (x < 0 || y < 0 || x >= s->width || y >= s->height) return 1;
    for (int i = 0; i < s->snake_count; i++) {
        if (!s->snakes[i].alive) continue;
        for (int k = 0; k < s->snakes[i].length; k++)
            if (s->snakes[i].body[k].x == x && s->snakes[i].body[k].y == y) return 1;
    }
    return 0;
}

int think(const State *s) {
    Point head = s->snakes[s->me].body[0];
    int best = -100000, dir = UP;
    for (int d = 0; d < 4; d++) {
        int x = head.x + DX[d], y = head.y + DY[d], score = 0, near = 999, i;
        if (blocked(s, x, y)) continue;
        for (i = 0; i < 4; i++) if (!blocked(s, x + DX[i], y + DY[i])) score += 5;
        for (i = 0; i < s->food_count; i++) {
            int dist = abs(s->food[i].x - x) + abs(s->food[i].y - y);
            if (dist < near) near = dist;
        }
        score -= near;
        if (score > best) { best = score; dir = d; }
    }
    return dir;
}

// 贪吃蛇:选空间最大的方向,再靠近果子。
use npe::Json;

const DIRS: [(i32, i32); 4] = [(0, -1), (1, 0), (0, 1), (-1, 0)];

fn think(obs: &Json) -> String {
    let (w, h) = (obs.int("width"), obs.int("height"));
    let mut wall = vec![vec![false; w as usize]; h as usize];
    for s in obs.get("snakes").items() {
        for c in s.grid("body") {
            wall[c[1] as usize][c[0] as usize] = true;
        }
    }
    let free = |g: &Vec<Vec<bool>>, x: i32, y: i32| x >= 0 && y >= 0 && x < w && y < h && !g[y as usize][x as usize];
    let head = obs.get(&format!("snakes[{}].body[0]", obs.int("me"))).clone();
    let (hx, hy) = (head.int("[0]"), head.int("[1]"));
    let food = obs.grid("food");
    let (mut best, mut dir) = (i32::MIN, 0);
    for (d, (dx, dy)) in DIRS.iter().enumerate() {
        let (x, y) = (hx + dx, hy + dy);
        if !free(&wall, x, y) {
            continue;
        }
        let mut g = wall.clone();
        let mut stack = vec![(x, y)];
        let mut area = 0;
        g[y as usize][x as usize] = true;
        while let Some((a, b)) = stack.pop() {
            area += 1;
            for (dx, dy) in DIRS {
                if free(&g, a + dx, b + dy) {
                    g[(b + dy) as usize][(a + dx) as usize] = true;
                    stack.push((a + dx, b + dy));
                }
            }
        }
        let near = food.iter().map(|f| (f[0] - x).abs() + (f[1] - y).abs()).min().unwrap_or(0);
        let score = area * 10 - near;
        if score > best {
            best = score;
            dir = d as i32;
        }
    }
    npe::action(&[("dir", dir)])
}

